"""Offline estimate for the initials-propagation idea on round_0 raw entities.
Prints counts only (no dialogue text)."""
import json, re, collections, sys

RAW = "/tmp/local_results/candidate/round_0/raw"
B = "/workspace/edshield-evidence"
DOCS = {"deterministic": B + "/experiments/genre_shift/data/planted/{}.jsonl",
        "llm": B + "/data/planted_llm/{}.jsonl",
        "control": B + "/experiments/genre_shift/data/control/{}.jsonl"}
NAME_LABELS = {"NAME_STUDENT", "NAME_RELATED"}
CUES = {
    "strict": r"(?:(?<=,[ \t])|(?<=:[ \t])|(?<=[-–][ \t])|(?<=^))",
    "loose": r"(?<![\w.'’])",
}


def initials(ents):
    out = {}
    for e in ents:
        if e["label"] in NAME_LABELS and (e["source"] != "model" or e["confidence"] >= 0.75):
            tok = e["text"].strip().split()[0] if e["text"].strip() else ""
            if len(tok) >= 2 and tok[0].isalpha():
                out.setdefault(tok[0].upper(), e["label"])
    return out


def new_spans(text, ents, cue):
    add = []
    for letter in initials(ents):
        for m in re.finditer(cue + re.escape(letter) + r"\.(?!\w)", text, re.M):
            if any(e["start"] < m.end() and m.start() < e["end"] for e in ents):
                continue
            add.append((m.start(), m.end()))
    return add


for cname, cue in CUES.items():
    print("==", cname)
    for view in ("deterministic", "llm", "control"):
        for ds in ("comta", "mathdial"):
            docs = {json.loads(l)["doc_id"]: json.loads(l) for l in open(DOCS[view].format(ds))}
            gained = n_ini = n_new = tok = 0
            for l in open(f"{RAW}/{view}__{ds}.jsonl"):
                r = json.loads(l); d = docs[r["doc_id"]]; t = d["text"]
                tok += len(t.split())
                add = new_spans(t, r["entities"], cue)
                n_new += len(add)
                if view == "control":
                    continue
                spans = d["meta"]["spans"] if "spans" in d.get("meta", {}) else d["gold_spans"]
                for s in spans:
                    if re.fullmatch(r"[A-Z]\.", s["text"]):
                        n_ini += 1
                        if any(a <= s["start"] and s["end"] <= b for a, b in add):
                            gained += 1
            extra = f" (+{1000*n_new/tok:.3f} flags/1k tok, {n_new} flags)" if view == "control" else f" new flags {n_new}"
            print(f"{view:13s} {ds:9s} initials {n_ini:4d} newly covered {gained:4d}{extra}")

